import { test, expect } from '@playwright/test';

test.describe('Checkout Flow - Complete Purchase', () => {
  const BASE_URL = 'https://www.saucedemo.com';
  const USERNAME = 'standard_user';
  const PASSWORD = 'secret_sauce';

  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto(BASE_URL);

    // Login with standard_user credentials
    await page.getByLabel('Username').fill(USERNAME);
    await page.getByLabel('Password').fill(PASSWORD);
    await page.getByRole('button', { name: /login/i }).click();

    // Wait for inventory page to load
    await page.waitForURL('**/inventory.html');
  });

  test('should add backpack to cart and proceed to checkout', async ({ page }) => {
    // Add the backpack to cart
    await page.locator('[data-test="add-to-cart-sauce-labs-backpack"]').click();

    // Verify item was added (cart badge should show 1)
    const cartBadge = page.locator('.shopping_cart_badge');
    await expect(cartBadge).toContainText('1');

    // Click on the shopping cart link
    await page.locator('.shopping_cart_link').click();

    // Wait for cart page to load
    await page.waitForURL('**/cart.html');

    // Verify the backpack is in the cart
    await expect(page.getByText('Sauce Labs Backpack')).toBeVisible();

    // Click the checkout button
    await page.locator('[data-test="checkout"]').click();

    // Wait for checkout page to load
    await page.waitForURL('**/checkout-step-one.html');

    // Verify we're on the checkout information form
    await expect(page.getByText(/checkout: your information/i)).toBeVisible();
  });

  test('should complete full checkout with order confirmation', async ({ page }) => {
    // Add the backpack to cart
    await page.locator('[data-test="add-to-cart-sauce-labs-backpack"]').click();

    // Navigate to cart
    await page.locator('.shopping_cart_link').click();
    await page.waitForURL('**/cart.html');

    // Click checkout
    await page.locator('[data-test="checkout"]').click();
    await page.waitForURL('**/checkout-step-one.html');

    // Fill in the checkout information form
    await page.locator('[data-test="firstName"]').fill('Saif');
    await page.locator('[data-test="lastName"]').fill('Afzal');
    await page.locator('[data-test="postalCode"]').fill('201301');

    // Click continue button
    await page.locator('[data-test="continue"]').click();

    // Wait for overview page to load
    await page.waitForURL('**/checkout-step-two.html');

    // Verify we're on the overview page
    await expect(page.getByText(/checkout: overview/i)).toBeVisible();

    // Verify item total is displayed
    const itemTotal = page.locator('[data-test="subtotal-label"]');
    await expect(itemTotal).toBeVisible();

    // Click the finish button to complete the order
    await page.locator('[data-test="finish"]').click();

    // Wait for confirmation page to load
    await page.waitForURL('**/checkout-complete.html');

    // Verify the confirmation header with the thank you message
    const confirmationHeader = page.locator('.complete-header');
    await expect(confirmationHeader).toContainText('Thank you for your order!');

    // Additional verification that we're on the complete page
    await expect(page.getByText(/your order has been dispatched/i)).toBeVisible();
  });
});
